from core import *

def critical_mixed(case):
 P=x*x*(x-1);w=1+x*x;A=s.Integer(4)
 ck('The double root has a quartic squared local profile',s.limit(P**2/x**4,x,0),1)
 ck('The simple root has a quadratic squared local profile',s.limit(P**2/(x-1)**2,x,1),1)
 ck('The weights at the two differently scaled roots',s.Matrix([w.subs(x,0),w.subs(x,1)]),s.Matrix([1,2]))
 analytic('Mixed root multiplicities select the dominant sublevel scale',['The weight is positive on the compact interval. The polynomial has a double root at zero and a simple root at one; both are interior.'],['Dominated difference quotients give the derivative difference as twice the weighted sublevel mass.','Outside fixed disjoint root neighborhoods the squared polynomial has a positive lower bound. Near zero its ratio to x^4 tends to one. Rescale x=a^(1/4)y; squeezing the boundaries between constant multiples tending to one gives weighted mass2a^(1/4)(1+o1).','Near one the local sublevel mass is4sqrt(a)(1+o1), which vanishes after division by a^(1/4). Multiplying the dominant mass by two gives4.'])
 return candidate(r'R(x)=x^2(x-1),\quad F(a)=\int_{-1}^{2}|R(x)^2-a|(1+x^2)\,\mathrm dx.'+T('The derivative at zero is the right derivative. Find ')+r'\lim_{a\downarrow0}\frac{F\prime(a)-F\prime(0+)}{a^{1/4}}.',A,[(2,'Omit the factor two from the absolute-value sign change'),(8,'Count both available sides twice'),(12,'Keep the simple-root contribution at the quartic-root scale'),(6,'Assign the weight at the simple root to the dominant root'),(1,'Count only one side and omit the sign-change factor'),(3,'Replace the fourth-root scale by its polynomial degree')],[r'F\prime(a)-F\prime(0+)=2\int_{\{x\in[-1,2]:R(x)^2<a\}}(1+x^2)\,\mathrm dx',T('Dominated difference quotients justify this derivative. Outside neighborhoods of zero and one, the squared polynomial is bounded away from zero.'),r'R(x)^2\sim x^4\quad(x\to0),\qquad R(x)^2\sim(x-1)^2\quad(x\to1)',T('The two interior roots therefore have different shrinking widths. At zero use the fourth-root scale; continuity of the weight and local boundary squeezing give the leading mass.'),r'\int_{\{R(x)^2<a\}\cap(-\epsilon,\epsilon)}(1+x^2)\,\mathrm dx=2a^{1/4}(1+o(1))',r'\int_{\{R(x)^2<a\}\cap(1-\epsilon,1+\epsilon)}(1+x^2)\,\mathrm dx=4\sqrt a(1+o(1))=o(a^{1/4})',r'\frac{F\prime(a)-F\prime(0+)}{a^{1/4}}\longrightarrow4'],'absolute-value-integral-mixed-quartic-and-quadratic-sublevels')

@register('differentiation','critical-level-absolute-integral','critical-level-sublevel-mass','local-root-rescaling-and-global-localization','An absolute-value integral becomes singular when a level passes a quadratic zero; one must distinguish interior roots from boundary roots and control the remainder away from every root.','This is a moving critical level inside a global integral, not a direct Leibniz boundary derivative.',[{'caseId':'root-geometry-'+str(i),'roots':roots,'bounds':bounds,'weight':weight,'purpose':'Change the number and location of critical roots, endpoint contributions, and nonconstant weights.'} for i,(roots,bounds,weight) in enumerate([([0,0,1],[-1,2],'1+x**2'),([-1,1],[-2,2],'1+x**2'),([0,2],[0,3],'1+x'),([-1,0,2],[-1,3],'2+x**2'),([0,1],[0,1],'1'),([-2,1],[-2,1],'1+x**2'),([-1,0,1],[-2,2],'1+x**2'),([-2,0,3],[-3,3],'4+x')])],['differentiation under an integral','simple roots','local inverse functions','one-sided limits'])
def critical(case):
 if case['roots']==[0,0,1]:return critical_mixed(case)
 roots=case['roots'];lo,hi=case['bounds'];w=s.sympify(case['weight'],locals={'x':x});P=s.prod(x-r for r in roots);terms=[]
 for r in roots:
  derivative=s.diff(P,x).subs(x,r);weight=w.subs(x,r);sides=1 if r in [lo,hi] else 2
  condition('Each root is simple and the weight there is positive',derivative!=0 and weight>0,'This makes the local sublevel length proportional to the square root of the level.')
  ck('The independent local square coefficient at root '+str(r),s.limit(P**2/(x-r)**2,x,r),derivative**2)
  terms.append(2*sides*weight/abs(derivative))
 A=sum(terms);allinterior=sum(4*w.subs(x,r)/abs(s.diff(P,x).subs(x,r)) for r in roots);squared=sum((2 if r in [lo,hi] else 4)*w.subs(x,r)/s.diff(P,x).subs(x,r)**2 for r in roots)
 ck('Derivative of the integrand on the two level regions',s.diff(P**2-t,t),-1)
 analytic('Differentiated sublevel mass',['The polynomial has precisely the displayed simple roots on the compact interval; the polynomial weight is nonnegative there.','The positive level tends to zero and all sufficiently small nonzero level sets are finite, hence have measure zero.'],['Dominated difference quotients give F prime(a)=integral w(2 indicator(P^2<a)-1). At zero the right derivative is minus integral w.','Outside disjoint small root neighborhoods the polynomial square has a positive minimum, so no sublevel mass remains there for small a.','At a simple root r, P(x)=P prime(r)(x-r)+O((x-r)^2). Each available side has weighted sublevel mass sqrt(a)w(r)/|P prime(r)|+o(sqrt(a)).','Multiply the mass by two and sum the sides. Endpoint roots have one side, interior roots two.'])
 return candidate(r'R(x)='+L(P)+r',\quad w(x)='+L(w)+r',\quad F(a)=\int_{'+str(lo)+'}^{'+str(hi)+r'}|R(x)^2-a|w(x)\,\mathrm{d}x.'+T('Determine the limit; the derivative at zero is the right derivative.')+r'\qquad\lim_{a\downarrow0}\frac{F\prime(a)-F\prime(0+)}{\sqrt a}',A,[(A/2,'Forget the factor two in the derivative of the absolute-value sign change'),(2*A,'Count both sides twice'),(allinterior,'Count every boundary root as an interior root'),(squared,'Use the squared local derivative instead of its magnitude'),(A/3,'Use the coefficient of the undifferentiated three-halves power without differentiating it'),(R(3,2)*A,'Differentiate the three-halves power but retain the wrong undifferentiated mass coefficient')],[T('Differentiate using dominated difference quotients. The sign changes only on the shrinking sublevel set.'),r'F\prime(a)-F\prime(0+)=2\int_{\{x\in['+str(lo)+','+str(hi)+r']:R(x)^2<a\}}w(x)\,\mathrm{d}x',T('Outside small neighborhoods of the displayed roots, the polynomial square has a positive lower bound. Only those neighborhoods contribute.'),r'R(x)^2=R\prime(r)^2(x-r)^2+O((x-r)^3)',r'\textnormal{One available side contributes }\frac{2w(r)}{|R\prime(r)|}\sqrt a+o(\sqrt a)',T('An interior root has two available sides; an endpoint root has one.'),r'\lim_{a\downarrow0}\frac{F\prime(a)-F\prime(0+)}{\sqrt a}='+r'+'.join(L(q) for q in terms)+'='+L(A)],'absolute-value-integral-critical-quadratic-sublevels')

@register('differentiation','moment-hankel-vandermonde','moment-determinant-antisymmetrization','permutation-expansion-and-Vandermonde-symmetry','Derivatives encode moments, but the determinant-to-integral normalization is fixed by antisymmetrizing two permutation sums and counting all variable permutations.','This uses an integral moment matrix and an antisymmetric product, not principal-minor deletion in a finite cyclic matrix.',[{'caseId':'size-'+str(r),'r':r,'a':a,'b':b,'purpose':'Vary matrix size and endpoint weight while keeping the same structural identity.'} for r,a,b in [(3,1,2),(4,2,1),(3,2,3),(5,1,3),(4,3,2),(6,2,2),(5,3,1),(6,1,2)]],['differentiation under an integral','determinants','permutations','Vandermonde determinant'])
def hankel(case):
 r=case['r'];a=case['a'];b=case['b'];mom=lambda j:s.factorial(a+j-1)*s.factorial(b-1)/s.factorial(a+b+j-1)
 H=s.Matrix(r,r,lambda i,j:mom(i+j));D=H.det();prod=s.prod(s.factorial(j)*s.factorial(a+j-1)*s.factorial(b+j-1)/s.factorial(a+b+r+j-2) for j in range(r));A=1/s.factorial(r)
 ck('The exact moment determinant independently matches the product evaluation',D,prod)
 # Andreief does not need the product evaluation: check permutation integration directly at the actual size.
 permutation_sum=0
 for perm in itertools.permutations(range(r)):
  inv=sum(perm[i]>perm[j] for i in range(r) for j in range(i+1,r));permutation_sum+=(-1)**inv*s.prod(mom(i+perm[i]) for i in range(r))
 ck('Independent signed permutation expansion integrates one determinant',permutation_sum,D)
 condition('The integral denominator is strictly positive',D>0,'A positive weight almost everywhere makes the moment Gram matrix positive definite.')
 analytic('Determinant integral identity',['The integer endpoint exponents are nonnegative, so every moment and derivative under the integral is dominated on bounded parameter intervals.','The Vandermonde product is nonzero away from coincidence hyperplanes, which have measure zero.'],['The derivative of order k at zero is the kth moment. Expand the determinant of its moment matrix as a signed permutation sum, and put its products under the multiple integral.','Antisymmetrize the monomial product against the Vandermonde determinant. Relabeling integration variables shows all r factorial antisymmetrized terms contribute equally.','The result is det(H)=1/r! times the integral of the squared Vandermonde with the product weight. Positivity permits division.'])
 w=x**(a-1)*(1-x)**(b-1)
 return candidate(r'f(t)=\int_0^1e^{tx}\left('+L(w)+r'\right)\,\mathrm{d}x,\quad H=(f^{(i+j)}(0))_{i,j=0}^{'+str(r-1)+r'}.'+r'\quad I=\int_{[0,1]^{'+str(r)+r'}}\prod_{j=1}^{'+str(r)+r'}x_j^{'+str(a-1)+r'}(1-x_j)^{'+str(b-1)+r'}\prod_{1\le i<j\le'+str(r)+r'}(x_i-x_j)^2\,\mathrm{d}x_1\cdots\mathrm{d}x_{'+str(r)+r'}.'+T('Find ')+r'\det(H)/I.',A,[(1/s.factorial(r-1),'Count only permutations fixing one coordinate'),(1/s.factorial(r+1),'Count a spurious additional integration coordinate'),(1/s.factorial(r)**2,'Divide twice for the two alternating sums'),(s.Integer(1),'Ignore the relabeling multiplicity'),(1/s.Integer(r),'Count cyclic permutations instead of all permutations'),(1/s.Integer(2)**r,'Replace permutation count by independent sign choices')],[r'\mu_k=f^{(k)}(0)=\int_0^1x^{k+'+str(a-1)+r'}(1-x)^{'+str(b-1)+r'}\,\mathrm{d}x,\qquad H_{ij}=\mu_{i+j}',T('Dominated differentiation is valid on this compact interval. Expand the moment determinant and move the finite sum inside the product integral.'),r'\det H=\int_{[0,1]^{'+str(r)+r'}}\left(\prod_{j=1}^{'+str(r)+r'}x_j^{j-1}w(x_j)\right)\det(x_j^{i-1})_{i,j=1}^{'+str(r)+r'}\,\mathrm{d}\mathbf x,\qquad w(x)=x^{'+str(a-1)+r'}(1-x)^{'+str(b-1)+r'}',T('Antisymmetrize the first monomial product. Relabeling the integration coordinates makes every permutation contribute the same signed determinant term.'),r'\det H=\frac1{'+str(r)+r'!}\int_{[0,1]^{'+str(r)+r'}}\prod_jw(x_j)\det(x_j^{i-1})^2\,\mathrm{d}\mathbf x=\frac I{'+str(r)+r'!}',T('The integral is positive because the weight is positive in the interior and coincident coordinates form a null set.')],'moment-Hankel-determinant-Vandermonde-factorial')

@register('differentiation','tree-resistance-sensitivity','weighted-tree-log-derivative-resistance','matrix-tree-theorem-and-electrical-potential','The derivative of a sum over all spanning trees is best found by turning a log determinant into an effective resistance; the selected edge probability and resistance differ by its conductance.','The cyclic determinant family differentiates a supplied matrix. Here the matrix must be discovered from a graph and the weighted combinatorial sum.',[{'caseId':'network-'+str(i),'vertices':nv,'edges':edges,'selected':sel,'at':at,'purpose':'Change graph topology, the varied edge, and competing weighted paths.'} for i,(nv,edges,sel,at) in enumerate([(5,[(0,1,2),(1,2,3),(2,3,1),(3,4,2),(4,0,3),(0,2,1),(1,3,2),(2,4,1)],0,3),(5,[(0,1,1),(0,2,2),(0,3,3),(0,4,1),(1,2,2),(2,3,1),(3,4,2),(4,1,3)],5,2),(6,[(0,3,1),(0,4,2),(0,5,3),(1,3,2),(1,4,1),(1,5,2),(2,3,3),(2,4,2),(2,5,1)],4,3),(6,[(0,1,1),(1,2,2),(2,3,3),(3,4,1),(4,5,2),(5,0,3),(0,3,2),(1,4,1),(2,5,2)],6,4),(5,[(i,j,(i+j)%3+1) for i in range(5) for j in range(i+1,5)],3,2),(6,[(0,1,2),(1,2,1),(2,0,3),(3,4,2),(4,5,3),(5,3,1),(0,3,2),(1,4,1),(2,5,3)],7,3),(6,[(0,1,1),(0,2,3),(0,3,2),(0,4,1),(0,5,2),(1,2,1),(2,3,2),(3,4,3),(4,5,1),(5,1,2)],1,4),(6,[(0,1,1),(1,2,1),(2,3,2),(3,4,3),(4,5,2),(5,0,1),(0,2,2),(1,3,3),(2,4,1),(3,5,2)],8,2)])],['spanning trees','weighted Laplacians','matrix determinant differentiation','linear systems'])
def tree(case):
 nv=case['vertices'];edges=case['edges'];sel=case['selected'];at=s.Integer(case['at']);lap=s.zeros(nv);weights=[]
 for e,(u,v,w) in enumerate(edges):
  weight=x if e==sel else s.Integer(w);weights.append(weight);lap[u,u]+=weight;lap[v,v]+=weight;lap[u,v]-=weight;lap[v,u]-=weight
 M=lap[:nv-1,:nv-1];u,v,_=edges[sel];bvec=s.zeros(nv-1,1)
 if u<nv-1:bvec[u]=1
 if v<nv-1:bvec[v]=-1
 M0=M.subs(x,at);potential=M0.inv()*bvec;A=s.factor((bvec.T*potential)[0]);poly=0;treecount=0
 for chosen in itertools.combinations(range(len(edges)),nv-1):
  parent=list(range(nv))
  def find(q):
   while parent[q]!=q:q=parent[q]
   return q
  for e in chosen:
   p,q,_=edges[e];parent[find(p)]=find(q)
  if len({find(q) for q in range(nv)})==1:poly+=s.prod(weights[e] for e in chosen);treecount+=1
 poly=s.expand(poly)
 ck('Independent weighted spanning-tree enumeration equals the Laplacian minor determinant',poly,M.det())
 ck('Independent differentiation of the enumerated polynomial gives the log derivative',s.diff(poly,x).subs(x,at)/poly.subs(x,at),A)
 ck('The displayed potential solves the grounded current system',M0*potential,bvec)
 condition('The graph is connected and has positive conductances',treecount>0 and at>0,'All other displayed edge weights are positive.')
 probability=at*A;reciprocal=1/A;direct=1/at
 edgeTeX=r'\{'+','.join('('+str(a+1)+','+str(b+1)+','+(r'x' if e==sel else str(w))+')' for e,(a,b,w) in enumerate(edges))+r'\}'
 return candidate(T('An undirected graph has vertices ')+r'1,\ldots,'+str(nv)+T('. Each triple below gives its two endpoints and positive edge weight; there are no other edges.')+edgeTeX+r'.\quad\tau(x)=\sum_{T\textnormal{ spanning tree}}\prod_{e\in T}w_e(x).'+T('Find ')+r'\left.\frac{\mathrm d}{\mathrm dx}\ln\tau(x)\right|_{x='+L(at)+r'}.',A,[(probability,'Return the edge-inclusion probability instead of dividing by its conductance'),(reciprocal,'Return effective conductance instead of effective resistance'),(direct,'Ignore all alternative paths between the selected endpoints'),(A/2,'Halve the current injection for an undirected edge'),(2*A,'Count both orientations as different varied edges'),(A/(1+at*A),'Apply the rank-one update formula once more after already substituting the varied conductance'),(A/(1-at*A),'Delete the varied edge before evaluating the stated derivative')],[T('Use the weighted matrix-tree theorem: the spanning-tree sum is any grounded Laplacian determinant. Ground the last vertex.'),r'L_0='+L(M0)+r',\qquad b='+L(bvec),r'\frac{\mathrm d}{\mathrm dx}\ln\det L(x)=\operatorname{tr}(L(x)^{-1}bb^{\mathsf T})=b^{\mathsf T}L(x)^{-1}b',r'L_0v=b,\qquad v='+L(potential),r'b^{\mathsf T}v='+L(A),T('All weights are positive and the graph is connected, so the grounded Laplacian is invertible. The derivative is the effective resistance, not the edge-inclusion probability.')],'weighted-spanning-tree-logarithmic-edge-sensitivity')

@register('differentiation','sharp-landau-bound','sharp-global-derivative-interpolation','two-sided-Taylor-optimization-and-smoothed-perfect-spline','A sharp derivative estimate needs a global two-sided comparison and an approximating smooth extremizer; the elementary one-sided estimate has the wrong constant.','The Hilbert and uniform polynomial bounds are finite-dimensional; this is a global bound for arbitrary twice continuously differentiable functions.',[{'caseId':'bounds-'+str(i),'M':M,'N':N,'purpose':'A distinct pair of function and second-derivative budgets; the supremum is not falsely asserted to be attained by a nonsmooth spline.'} for i,(M,N) in enumerate([(1,1),(1,3),(2,1),(2,3),(3,2),(R(1,2),3),(3,R(1,2)),(R(2,3),5)])],['Taylor theorem with remainder bounds','optimization','smooth approximation'])
def landau(case):
 M=R(case['M']);N=R(case['N']);A=s.sqrt(2*M*N);h=s.sqrt(2*M/N);upper=M/t+N*t/2
 ck('The two-sided Taylor bound is minimized at the displayed scale',s.diff(upper,t).subs(t,h),0);ck('The optimized upper bound',upper.subs(t,h),A)
 # A positive derivative peak evolves linearly down to zero under acceleration -N.
 peak=A;time=peak/N;excursion=s.integrate(peak-N*x,(x,0,time));ck('The extremal parabolic arc travels from zero to the amplitude bound',excursion,M)
 analytic('Sharp Landau inequality and mollified equality sequence',['The function is real and twice continuously differentiable on the whole real line; both uniform bounds hold globally.'],['For every t>0, subtract Taylor expansions at x+t and x-t. The difference of endpoint values is at most2M; the sum of remainder bounds is Nt^2. Hence |f prime(x)|<=M/t+Nt/2.','Optimize t=sqrt(2M/N). To show sharpness, take the periodic C1 perfect spline whose derivative is a triangle wave of height sqrt(2MN) and slope magnitude N, and whose function values oscillate between -M and M.','Convolve this periodic spline with nonnegative smooth probability mollifiers. Function amplitude remains at most M, the second derivative is at most N because the spline has an essentially bounded weak second derivative, and the derivative peak converges to sqrt(2MN). Thus the requested supremum is exact.'])
 return candidate(T('Over all real functions twice continuously differentiable on the entire real line and satisfying ')+r'|f(x)|\le'+L(M)+r',\quad|f^{\prime\prime}(x)|\le'+L(N)+r'\quad(x\in\mathbb R),'+T('find ')+r'\sup_f\sup_{x\in\mathbb R}|f\prime(x)|.',A,[(s.sqrt(M*N),'Omit one remainder contribution when optimizing the two-sided estimate'),(2*s.sqrt(M*N),'Use the weaker forward-only Taylor estimate'),(s.sqrt(M*N/2),'Use the interval half-width twice in the normalization'),(2*s.sqrt(2*M*N),'Double the optimized derivative bound'),(M*N,'Forget the square root forced by derivative scaling'),(s.sqrt(2*M/N),'Return the optimizing step size rather than the derivative bound')],[r'|2tf\prime(x)|\le|f(x+t)-f(x-t)|+Nt^2\le2M+Nt^2,\quad M='+L(M)+r',\ N='+L(N),r'|f\prime(x)|\le\frac Mt+\frac{Nt}{2}\quad(t>0)',r't=\sqrt{\frac{2M}{N}}\quad\Longrightarrow\quad|f\prime(x)|\le\sqrt{2MN}='+L(A),T('For sharpness, use a periodic continuously differentiable parabolic spline with amplitude M, second derivative of magnitude N away from its joining points, and triangular derivative peaks of height the displayed bound.'),r'\int_0^{\sqrt{2M/N}}(\sqrt{2MN}-Ns)\,\mathrm ds=M',T('Convolve with nonnegative smooth probability kernels. Both uniform bounds are preserved, while derivative peaks converge to the spline peak. These smooth admissible functions approach the bound, proving the supremum.')],'sharp-global-Landau-derivative-interpolation')
